INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 2, '{"stem": "补充问题并计算(2)：小海有18个空的盒子，将32个标本按每8个放一盒，（还有多少个空盒子）？"}', '14（个）', '32÷8=4, 18-4=14', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p100","buc_02"]', 1, NULL);
