INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 2, '{"stem": "应用(1)：王老师带了50元钱去超市买牛奶，每盒牛奶3元，她最多可以买多少盒牛奶？"}', '16（盒）', '50÷3=16……2, 最多16盒', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p101","apply_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 2, '{"stem": "应用(2)：超市里的妙芙蛋糕，4包装一盒，8盒装一箱，192包可以装多少箱？"}', '6（箱）', '192÷4=48盒, 48÷8=6箱', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p101","apply_02"]', 1, NULL);
