INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 2, '{"stem": "应用(4)：学校图书馆有科技书128本，漫画书的数量是科技书的4倍，漫画书比科技书多多少本？"}', '384（本）', '128×4=512, 512-128=384', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p101","apply_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1025, '数学', '三年级', 'apply', 2, '{"stem": "应用(5)：小华去买5支相同的钢笔，付给营业员150元，找回40元，每支钢笔多少元？"}', '22（元）', '150-40=110, 110÷5=22', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p101","apply_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'apply', 3, '{"stem": "应用(6)：奶奶去超市买白菜，有机白菜每包重500克，每包售价6元；普通白菜每包重3千克，每包售价24元，哪种白菜更便宜？"}', '普通白菜更便宜', '有机: 500g→6元, 1kg→12元; 普通: 3kg→24元, 1kg→8元; 12>8→普通便宜', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p101","apply_06"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 2, '{"stem": "应用(7)：三年级学生乘车去秋游，每辆车可乘45人，前4辆车全部坐满，第5辆车还有17个空位，一共有多少人参加秋游？"}', '208（人）', '45×4=180, 45-17=28, 180+28=208', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p101","apply_07"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 2, '{"stem": "应用(8)：超市把108包饼干平均分装在6个箱子里，如果一包饼干卖8元，一箱饼干卖多少元？"}', '144（元）', '108÷6=18包/箱, 18×8=144', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p101","apply_08"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 3, '{"stem": "应用(9)：工厂里有一堆重123吨的废料需要运送到环保站处理，如果使用载重5吨的卡车运送，最少要多少辆卡车才能运完？"}', '25（辆）', '123÷5=24……3, 24+1=25', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p101","apply_09"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 3, '{"stem": "应用(10)：小明家住在5楼，下楼要走80级楼梯。小华和小明住在同一栋楼里，但她住在3楼，小华下楼要走多少级楼梯？"}', '40（级）', '80÷(5-1)=20级/层, (3-1)×20=40', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p101","apply_10"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'apply', 3, '{"stem": "应用(11)：王阿姨想购置一组沙发，她家的客厅宽度是3米95厘米，这组沙发各部分长度分别为3dm、8dm、8dm、18dm、3dm，这组沙发能摆得下吗？"}', '摆不下', '3+8+8+18+3=40dm=400cm, 3m95cm=395cm, 400>395→摆不下', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p101","apply_11"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展(1)：草地上有白兔和灰兔一共168只，其中白兔的只数是灰兔的3倍，白兔和灰兔分别有多少只？"}', '白兔126只，灰兔42只', '灰兔=168÷(3+1)=42, 白兔=42×3=126', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p103","extend_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1035, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展(2)：星期日，果果在家里写作业，她刚写了5分钟，便听见家里的钟响了一下；过了一会儿，她又听见钟响了一下；又过了一会儿，她又听见钟响了一下；再过了一会儿，她听见钟响两下，这时她的作业写完了。果果是在什么时刻开始写作业的？（钟几时响几下，半时响一下）"}', '12:30', '钟半时响1下, 整时响几时数下。连续3下=半时→1:00→1:30, 然后2:00响2下。开始=12:30, 写5分钟→12:35响(12:30半时), 1:00响1下, 1:30响1下, 2:00响2下→结束', 'jsj3_sx_v118', '["jsj3_sx","zhuanxiang3_2","p103","extend_02"]', 1, NULL);